#!/bin/zsh
cd "$(dirname "$0")"
A=$(cat avatar-base.url); V=$(cat original/ref.url)
MOTION='Raw iPhone front-camera selfie video, locked-off camera, 9:16. The woman does her foundation routine in the bathroom with a deadpan, unbothered expression, never speaking, mouth closed. 0-1s: she pumps beige foundation from the bottle onto the makeup sponge, looking down. 1-3s: she dabs the sponge on her right cheek with quick small taps, eyes half closed. 3-4s: she rubs foundation across her forehead with her fingertips. 4-5s: she blends her cheek with her fingers and tilts her head slightly. 5-6s: she taps the sponge under her eye next to her nose. 6-7s: she dabs her other cheek. 7-8s: she rubs her forehead again, then glances flatly at the camera. Natural blinking, small casual movements, same face, hair, blue bow headband and white tank top throughout. Available bathroom light, natural grain. No text, no captions.'
NEG='extra fingers, deformed hands, melting fingers, face morphing, identity drift, changing clothes, changing hairstyle, talking, open mouth speaking, subtitles, text overlay, watermark, studio lighting, camera zoom, camera movement, cut to another shot'
run(){ n=$1; shift; wavespeed run "$@" --download clipes/$n.mp4 --json > logs/$n.json 2>&1; echo "$n exit=$?"; }
run kling-i2v kwaivgi/kling-v3.0-std/image-to-video -i image=$A -i duration=8 -i sound=false -i cfg_scale=0.5 -i prompt="$MOTION" -i negative_prompt="$NEG" &
run kling-motion kwaivgi/kling-v3.0-std/motion-control -i image=$A -i video=$V -i character_orientation=video -i keep_original_sound=false -i prompt="A woman doing her foundation makeup routine in a bathroom, deadpan expression, mouth closed, raw iPhone selfie video, no text on screen." -i negative_prompt="$NEG" &
run seedance-i2v bytedance/seedance-2.0/image-to-video -i image=$A -i prompt="$MOTION" -i duration=8 -i resolution=720p -i aspect_ratio=9:16 -i generate_audio=false &
run seedance-edit bytedance/seedance-2.0/video-edit -i video=$V -i "reference_images=[\"$A\"]" -i resolution=720p -i aspect_ratio=9:16 -i generate_audio=false -i prompt="Replace the woman in the video with the woman from the reference image: her face, dark brown hair, skin tone and beauty mark. Keep every movement, gesture, timing, camera framing, the blue bow headband, white tank top, makeup sponge, foundation bottle and bathroom exactly as in the original video. Remove the yellow on-screen text caption at the top; show only the bathroom wall there." &
run gemini-i2v google/gemini-omni-1.1-flash/image-to-video -i image=$A -i prompt="$MOTION" -i duration=8 -i resolution=720p -i aspect_ratio=9:16 &
wait; echo TODOS_FIM
